const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
let index = 0;

const n = input[index++];
const t = new Array(n + 1);
for (let i = 1; i <= n; i++) {
    t[i] = input[index++];
}

const UP = 0, DOWN = 1, LEFT = 2, RIGHT = 3;
const UPLEFT = 4, UPRIGHT = 5, DOWNLEFT = 6, DOWNRIGHT = 7;

const dx = [0, 0, -1, 1, -1, 1, -1, 1];
const dy = [1, -1, 0, 0, 1, 1, -1, -1];

const rotation = [
    [UPLEFT, UPRIGHT],
    [DOWNLEFT, DOWNRIGHT],
    [UPLEFT, DOWNLEFT],
    [UPRIGHT, DOWNRIGHT],
    [UP, LEFT],
    [UP, RIGHT],
    [DOWN, LEFT],
    [DOWN, RIGHT]
];

const MAX = 5 * 30 + 5;
const SIZE = 2 * MAX;

function encodeState(x, y, dir, lev, far) {
    return ((((x * SIZE + y) * 8 + dir) * 32 + lev) * 6 + far);
}

const marked = new Set();
const positions = new Set();
const queue = [];
let head = 0;

const initialState = encodeState(MAX, MAX, UP, 1, 1);
marked.add(initialState);
positions.add(MAX * SIZE + MAX);
queue.push(initialState);

while (head < queue.length) {
    let state = queue[head++];

    const far = state % 6;
    state = (state - far) / 6;

    const lev = state % 32;
    state = (state - lev) / 32;

    const dir = state % 8;
    const position = (state - dir) / 8;

    const x = Math.floor(position / SIZE);
    const y = position % SIZE;

    positions.add(position);

    if (lev === n + 1) {
        continue;
    }

    if (far !== t[lev]) {
        const x2 = x + dx[dir];
        const y2 = y + dy[dir];
        const nextState = encodeState(x2, y2, dir, lev, far + 1);

        if (!marked.has(nextState)) {
            marked.add(nextState);
            queue.push(nextState);
        }
    } else {
        const dirs = rotation[dir];

        for (const nextDir of dirs) {
            const nextState = encodeState(x, y, nextDir, lev + 1, 0);

            if (!marked.has(nextState)) {
                marked.add(nextState);
                queue.push(nextState);
            }
        }
    }
}

