const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
let inputIndex = 0;

const UP = 0, DOWN = 1, LEFT = 2, RIGHT = 3;
const UPLEFT = 4, UPRIGHT = 5, DOWNLEFT = 6, DOWNRIGHT = 7;

const dx = [0, 0, -1, 1, -1, 1, -1, 1];
const dy = [1, -1, 0, 0, 1, 1, -1, -1];

const rotations = [
    [UPLEFT, UPRIGHT],
    [DOWNLEFT, DOWNRIGHT],
    [UPLEFT, DOWNLEFT],
    [UPRIGHT, DOWNRIGHT],
    [UP, LEFT],
    [UP, RIGHT],
    [DOWN, LEFT],
    [DOWN, RIGHT]
];

const MAX = 5 * 30 + 5;
const SIZE = 2 * MAX;
const TOTAL_STATES = SIZE * SIZE * 8 * 32 * 6;

const marked = new Uint8Array(Math.ceil(TOTAL_STATES / 8));
const visitedPoints = new Uint8Array(SIZE * SIZE);

function encode(x, y, dir, lev, far) {
    return (((x * SIZE + y) * 8 + dir) * 32 + lev) * 6 + far;
}

function isMarked(state) {
    return (marked[Math.floor(state / 8)] & (1 << (state & 7))) !== 0;
}

function mark(state) {
    marked[Math.floor(state / 8)] |= 1 << (state & 7);
}

const n = input[inputIndex++];
const t = new Array(n + 1);

for (let i = 1; i <= n; i++) {
    t[i] = input[inputIndex++];
}

let ans = 1;
let initialState = encode(MAX, MAX, UP, 1, 1);
let queue = [initialState];
let head = 0;

mark(initialState);
visitedPoints[MAX * SIZE + MAX] = 1;

while (head < queue.length) {
    let state = queue[head++];

    let value = state;
    const far = value % 6;
    value = Math.floor(value / 6);

    const lev = value % 32;
    value = Math.floor(value / 32);

    const dir = value % 8;
    const position = Math.floor(value / 8);

    const y = position % SIZE;
    const x = Math.floor(position / SIZE);

    const pointIndex = x * SIZE + y;
    if (visitedPoints[pointIndex] === 0) {
        visitedPoints[pointIndex] = 1;
        ans++;
    }

    if (lev === n + 1) {
        continue;
    }

    if (far !== t[lev]) {
        const x2 = x + dx[dir];
        const y2 = y + dy[dir];
        const nextState = encode(x2, y2, dir, lev, far + 1);

        if (!isMarked(nextState)) {
            mark(nextState);
            queue.push(nextState);
        }
    } else {
        const dirs = rotations[dir];

        let nextState = encode(x, y, dirs[0], lev + 1, 0);
        if (!isMarked(nextState)) {
            mark(nextState);
            queue.push(nextState);
        }

        nextState = encode(x, y, dirs[1], lev + 1, 0);
        if (!isMarked(nextState)) {
            mark(nextState);
            queue.push(nextState);
        }
    }

    if (head > 1000000 && head * 2 > queue.length) {
        queue = queue.slice(head);
        head = 0;
    }
}

